import my_memviz


class FakeTensor:
    def __init__(self, num_elements, element_size):
        self._num = num_elements
        self._esize = element_size

    def nelement(self):
        return self._num

    def element_size(self):
        return self._esize


def test_format_bytes_thousands_separator():
    assert my_memviz.format_bytes(1000) == "1,000"


def test_format_bytes_large():
    assert my_memviz.format_bytes(1234567) == "1,234,567"


def test_calculate_tensor_memory_basic():
    t = FakeTensor(100, 4)
    assert my_memviz.calculate_tensor_memory(t) == 400


def test_calculate_tensor_memory_zero_elements():
    t = FakeTensor(0, 4)
    assert my_memviz.calculate_tensor_memory(t) == 0


def test_calculate_tensor_memory_large():
    t = FakeTensor(1000000, 8)
    assert my_memviz.calculate_tensor_memory(t) == 8000000


def test_calculate_tensor_memory_uses_methods():
    class SpyTensor:
        def __init__(self):
            self.nelement_called = False
            self.element_size_called = False

        def nelement(self):
            self.nelement_called = True
            return 10

        def element_size(self):
            self.element_size_called = True
            return 2

    t = SpyTensor()
    result = my_memviz.calculate_tensor_memory(t)
    assert result == 20
    assert t.nelement_called
    assert t.element_size_called
